export type DictType = "size" | "status";

interface DictOption {
    value: string | number;
    label: string;
    color?: string;
}

/**
 * 字典参数
 */
const dictObjs: Record<DictType, DictOption[]> = {
    status: [
        { value: 0, label: "启用" },
        { value: 1, label: "停用" },
    ],
    size: [
        { value: 0, label: "男" },
        { value: 1, label: "女" },
    ]
}


/**
 * 字典管理
 */
class Dict {

    get(key: DictType){
        return dictObjs[key];
    }

    /**
     * 返回int 类型数据
     */
    getInt(key: DictType){
        return dictObjs[key].map((o) => ({ value: Number(o.value), ...o }))
    }

    /**
     * 返回String 类型数据
     */
    getString(key: DictType){
        return dictObjs[key].map((o) => ({ value: String(o.value), ...o }))
    }
}


export default new Dict();