import { Avatar, Button, Card, Form, FormInstance, Grid, List, Message, Space, Tabs } from "@arco-design/web-react";
import { IconCamera } from "@arco-design/web-react/icon";
import { useObserver } from "mobx-react-lite";
import styles from './index.module.less';
import React, { useRef } from "react";
import { SchemaForm } from '@system/schema';
import { Pattern } from "../../types/pattern";
import dict from "../../store/dict";
import utils from "utils";
import AsyncButton from "@system/AsyncButton";
import i18next from "i18next";
import UploadImg from "@system/UploadImg";
import user from '../../store/user';


const { t } = i18next;
const { ajax } = utils;

const MyIndex = () => {


    return useObserver(() => {
        const userInfo = user.info;

        const form = useRef<FormInstance>()
        const form2 = useRef<FormInstance>()

        if(!user.isLogin) return null;

        return (
            <Grid.Row gutter={[16,16]}>
                <Grid.Col span={8}>
                    <Card title={t('user.info')} bordered={false}>
                        <div style={{ display: "flex", justifyContent: "center" }}>
                            <div>
                            <UploadImg value={[]}
                                onChange={(url: string) => {
                                    return ajax.post('/apijson/put', {
                                        User: {
                                            login_name: userInfo.login_name,
                                            avatar: url,
                                        }
                                    }).then((res) => {
                                        user.assign({ avatar: url })
                                    })
                                }}
                            >
                                <Avatar triggerIcon={<IconCamera />} triggerType='mask' style={{ width: 100, height: 100 }}>
                                    {userInfo.avatar? <img alt='avatar' src={userInfo.avatar}/> : userInfo.login_name}
                                </Avatar>
                            </UploadImg>
                            </div>
                        </div>
                        <List
                            bordered={false}
                            className={styles.myList}
                            size='small'
                            dataSource={[
                                { title: t('user.name'), value: userInfo.login_name },
                                { title: t('user.phone'), value: userInfo.phonenumber },
                                { title: t('user.email'), value: userInfo.email },
                                { title: t('user.role'), value: userInfo.roles.map((o) => o.roleName).join('、') },
                                { title: t('creation.date'), value: userInfo.create_by },
                            ]}
                            render={(item, index) => {
                                return (
                                    <List.Item key={index} style={{ padding: "8px 0px" }}>
                                        <strong>{item.title}</strong>
                                        <span>
                                            {item.value}
                                        </span>
                                    </List.Item>
                                )
                            }}
                        />
                    </Card>
                </Grid.Col>
                <Grid.Col span={16}>
                    <Tabs className="bg-white">
                        <Tabs.TabPane title={t('basic.info')} key="baseInfo">
                            <div className="flex justify-end p-2">
                                <AsyncButton type="primary"
                                    onClick={() => {
                                        return form.current.validate().then((data) => {
                                            return ajax.post('/apijson/put', {
                                                User: {
                                                    login_name: userInfo.login_name,
                                                    ...data,
                                                }
                                            }).then((res) => {
                                                Message.success(t('save.success'));
                                                user.assign(data)
                                            })
                                        })
                                    }}
                                >{t('sys.save')}</AsyncButton>
                            </div>
                            <SchemaForm
                                ref={form}
                                initialValues={{
                                    user_name: userInfo.user_name,
                                    phonenumber: userInfo.phonenumber,
                                    email: userInfo.email,
                                    sex: userInfo.sex,
                                }}
                                labelWidth={150}
                                schema={{
                                    type: "object",
                                    properties: {
                                        user_name: { type: "string", title: t('user.nickname') },
                                        phonenumber: { type: "string", title: t('sys.phone'), pattern: Pattern.phone },
                                        email: { type: "string", title: t('sys.email'), pattern: Pattern.email },
                                        sex: { type: "string", title: t('sys.gender'), format: "radio", enum: dict.get("size") },
                                    },
                                    required: ['user_name', 'phonenumber', 'email']
                                }}
                            >
                            </SchemaForm>
                        </Tabs.TabPane>
                        <Tabs.TabPane title={t('change.password')} key="password">
                            <div className="flex justify-end p-2">
                                <AsyncButton type="primary"
                                    onClick={() => {
                                    }}
                                >{t('sys.save')}</AsyncButton>
                            </div>
                            <SchemaForm
                                ref={form2}
                                initialValues={{}}
                                labelWidth={150}
                                schema={{
                                    type: "object",
                                    properties: {
                                        oldPassword: { type: "string", title: t('old.password') },
                                        password: { type: "string", title: t('new.password') },
                                        password2: { 
                                            type: "string", title: t('confirm.password'),
                                            formItemProps: {
                                                validator(formData, callback) {
                                                    const { password, password2 } = formData;
                                                    if(password2 !== password){
                                                        callback(t('password.mismatch'))
                                                    }
                                                },
                                            }
                                        },
                                    },
                                    required: ['oldPassword', 'password', 'password2']
                                }}
                            >
                                <div style={{ marginLeft: 100 }}>
                                    <AsyncButton type="primary"
                                        onClick={() => {
                                            return form2.current.validate().then((data) => {
                                                return ajax.post('/userinfo/password', {
                                                    ...data,
                                                }, { encrypt: "all" }).then((res) => {
                                                    Message.success(t('password.update.success'))
                                                    form2.current.resetFields()
                                                })
                                            })
                                        }}
                                    >{t('sys.save')}</AsyncButton>
                                </div>
                            </SchemaForm>
                        </Tabs.TabPane>
                    </Tabs>
                </Grid.Col>
            </Grid.Row>
        )
    })
}


export default MyIndex;